// UUIDv7 identifiers generated by the application (plan §6.2, RFC 9562 §5.7).
//
// PostgreSQL 18 has a built-in uuidv7(), but cloud sessions run PostgreSQL 16 (plan §3.2), so
// the database never generates v7 ids: every id column has the fallback DEFAULT
// gen_random_uuid() (v4) for hand-written SQL, and Drizzle fills in uuidv7() through $defaultFn.
//
// Layout: 48-bit Unix time in milliseconds | version 7 | 12-bit counter | variant 0b10 | 62
// random bits. The 12-bit field is a counter (RFC 9562 §6.2, method 1) seeded with a random
// value below 2048 at every new millisecond, so ids from one process are strictly increasing
// even within the same millisecond; when the counter overflows the timestamp moves forward by
// one millisecond, and a clock that goes backwards never makes ids decrease.

import { randomFillSync } from 'node:crypto';

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

let lastMs = -1;
let counter = 0;

const HEX: string[] = Array.from({ length: 256 }, (_, i) => i.toString(16).padStart(2, '0'));

/** Formats 16 bytes as a lowercase, hyphenated UUID string. */
export function formatUuid(bytes: Uint8Array): string {
  if (bytes.length !== 16) throw new Error(`a UUID has 16 bytes, got ${bytes.length}`);
  let out = '';
  for (let i = 0; i < 16; i++) {
    if (i === 4 || i === 6 || i === 8 || i === 10) out += '-';
    out += HEX[bytes[i]!];
  }
  return out;
}

/**
 * Builds UUIDv7 bytes from a millisecond timestamp, a 12-bit counter and 8 random bytes (of
 * which 62 bits are used). Exposed for the deterministic fixture generator (src/fixtures).
 */
export function uuidv7FromParts(ms: number, counter12: number, random: Uint8Array): string {
  if (!Number.isInteger(ms) || ms < 0 || ms > 0xffff_ffff_ffff) {
    throw new Error(`UUIDv7 timestamp out of range: ${ms}`);
  }
  if (!Number.isInteger(counter12) || counter12 < 0 || counter12 > 0xfff) {
    throw new Error(`UUIDv7 counter out of range: ${counter12}`);
  }
  if (random.length < 8) throw new Error('UUIDv7 needs 8 random bytes');
  const b = new Uint8Array(16);
  // 48-bit big-endian timestamp. Division instead of bit shifts: JS bitwise ops are 32-bit.
  let t = ms;
  for (let i = 5; i >= 0; i--) {
    b[i] = t % 256;
    t = Math.floor(t / 256);
  }
  b[6] = 0x70 | (counter12 >> 8); // version 7 + high 4 bits of the counter
  b[7] = counter12 & 0xff;
  b[8] = 0x80 | (random[0]! & 0x3f); // variant 0b10
  for (let i = 1; i < 8; i++) b[8 + i] = random[i]!;
  return formatUuid(b);
}

/** A new UUIDv7, monotonic within this process. */
export function uuidv7(now: number = Date.now()): string {
  const random = new Uint8Array(10);
  randomFillSync(random);
  if (now > lastMs) {
    lastMs = now;
    // Random start below 2048 leaves at least 2048 increments before overflow.
    counter = ((random[8]! << 8) | random[9]!) & 0x7ff;
  } else {
    counter += 1;
    if (counter > 0xfff) {
      lastMs += 1;
      counter = 0;
    }
  }
  return uuidv7FromParts(lastMs, counter, random.subarray(0, 8));
}

/** The version nibble of a UUID string (7 for UUIDv7), or null when it is not a UUID. */
export function uuidVersion(id: string): number | null {
  const s = id.toLowerCase();
  if (!UUID_RE.test(s)) return null;
  return Number.parseInt(s[14]!, 16);
}

/** True for a UUID string with version 7 and the RFC 9562 variant. */
export function isUuidv7(id: string): boolean {
  if (uuidVersion(id) !== 7) return false;
  const variant = Number.parseInt(id[19]!, 16);
  return (variant & 0xc) === 0x8;
}

/** The Unix time in milliseconds stored in a UUIDv7. */
export function uuidv7Timestamp(id: string): number {
  if (!isUuidv7(id)) throw new Error(`not a UUIDv7: ${id}`);
  return Number.parseInt(id.slice(0, 8) + id.slice(9, 13), 16);
}
